#!/usr/bin/env python3
"""
UK Retail Fuel Price Trend Analysis — February 2026
Generates a professional HTML report from data.csv
"""

import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import seaborn as sns
from io import BytesIO
import base64
from datetime import datetime

# ── Configuration ──────────────────────────────────────────────────────────
INPUT_CSV = '/app/benchmark/data.csv'
OUTPUT_HTML = '/app/output/final_report.html'

plt.rcParams.update({
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.titlesize': 14,
    'axes.labelsize': 12,
    'figure.facecolor': 'white',
    'axes.facecolor': '#fafafa',
    'axes.grid': True,
    'grid.alpha': 0.3,
})

PALETTE = {
    'primary': '#1a5276',
    'secondary': '#2980b9',
    'accent': '#e67e22',
    'danger': '#c0392b',
    'success': '#27ae60',
    'light_bg': '#f8f9fa',
    'dark_text': '#2c3e50',
}

FUEL_COLORS = {
    'E10': '#2980b9',
    'B7_STANDARD': '#e67e22',
    'E5': '#8e44ad',
    'B7_PREMIUM': '#c0392b',
    'B10': '#27ae60',
    'SDV': '#16a085',
}

# ── Helper: figure → base64 ───────────────────────────────────────────────
def fig_to_base64(fig, dpi=150):
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    encoded = base64.b64encode(buf.read()).decode('utf-8')
    plt.close(fig)
    return encoded


def img_tag(b64, alt='Chart'):
    return f'<img src="data:image/png;base64,{b64}" alt="{alt}" style="max-width:100%;height:auto;display:block;margin:0 auto;" />'


# ── Load data ──────────────────────────────────────────────────────────────
df = pd.read_csv(INPUT_CSV, parse_dates=['recorded_at', 'source_updated_at'])

# ── Derived columns ────────────────────────────────────────────────────────
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600

# ── Section 1: Dataset Overview ────────────────────────────────────────────
total_records = len(df)
unique_stations = df['node_id'].nunique()
fuel_types = sorted(df['fuel_type'].unique())
date_range_start = df['recorded_at'].min()
date_range_end = df['recorded_at'].max()
missing_values = df.isnull().sum()
missing_total = missing_values.sum()
duplicate_rows = df.duplicated().sum()

# ── Section 2: Price Distribution by Fuel Type ────────────────────────────
price_stats = (
    df.groupby('fuel_type')['price_pence']
    .agg(['count', 'mean', 'median', 'std', 'min', 'max'])
    .rename(columns={
        'count': 'Records',
        'mean': 'Mean (ppl)',
        'median': 'Median (ppl)',
        'std': 'Std Dev',
        'min': 'Min (ppl)',
        'max': 'Max (ppl)',
    })
    .sort_values('Mean (ppl)', ascending=False)
)

# ── Section 3: Price Spread & Competitiveness ──────────────────────────────
spread_stats = (
    df.groupby('fuel_type')['price_pence']
    .agg(
        q25=lambda x: x.quantile(0.25),
        q75=lambda x: x.quantile(0.75),
        iqr=lambda x: x.quantile(0.75) - x.quantile(0.25),
        price_range=lambda x: x.max() - x.min(),
        min_val='min',
        max_val='max',
    )
    .sort_values('price_range', ascending=False)
)

# ── Section 4: Update Freshness ────────────────────────────────────────────
lag_overall_median = df['update_lag_hours'].median()
lag_overall_mean = df['update_lag_hours'].mean()
lag_by_fuel = (
    df.groupby('fuel_type')['update_lag_hours']
    .agg(['median', 'mean', 'count'])
    .rename(columns={'median': 'Median Lag (hrs)', 'mean': 'Mean Lag (hrs)', 'count': 'Records'})
    .sort_values('Median Lag (hrs)', ascending=False)
)

# Stale data: lag > 48 hours
stale_threshold = 48
stale_count = (df['update_lag_hours'] > stale_threshold).sum()
stale_pct = stale_count / len(df) * 100
very_stale_count = (df['update_lag_hours'] > 168).sum()  # >1 week
very_stale_pct = very_stale_count / len(df) * 100

# Stale stations
stale_station_data = df[df['update_lag_hours'] > stale_threshold].groupby('node_id').size().reset_index(name='stale_records')
stale_station_count = stale_station_data['node_id'].nunique()

# Fresh data: lag < 1 hour
fresh_count = (df['update_lag_hours'] < 1).sum()
fresh_pct = fresh_count / len(df) * 100

# ── Section 5: Station Coverage ────────────────────────────────────────────
fuels_per_station = df.groupby('node_id')['fuel_type'].nunique()
stations_per_fuel = df.groupby('fuel_type')['node_id'].nunique().sort_values(ascending=False)

# ── Generate Charts ────────────────────────────────────────────────────────

# Chart 1: Box plot of price by fuel type
fig1, ax1 = plt.subplots(figsize=(10, 6))
fuel_order = df.groupby('fuel_type')['price_pence'].median().sort_values().index.tolist()
box_data = [df[df['fuel_type'] == ft]['price_pence'].values for ft in fuel_order]
bp = ax1.boxplot(box_data, labels=fuel_order, patch_artist=True, showfliers=True,
                 flierprops=dict(marker='o', markersize=3, alpha=0.3),
                 medianprops=dict(color='black', linewidth=2))
for patch, ft in zip(bp['boxes'], fuel_order):
    patch.set_facecolor(FUEL_COLORS.get(ft, '#95a5a6'))
    patch.set_alpha(0.7)
ax1.set_ylabel('Price (pence per litre)')
ax1.set_xlabel('Fuel Type')
ax1.set_title('Price Distribution by Fuel Type')
fig1.tight_layout()
chart1_b64 = fig_to_base64(fig1)

# Chart 2: Violin plot
fig2, ax2 = plt.subplots(figsize=(10, 6))
# Filter to major fuel types for readability
major_fuels = df['fuel_type'].value_counts().head(4).index.tolist()
df_major = df[df['fuel_type'].isin(major_fuels)]
sns_violin_order = df_major.groupby('fuel_type')['price_pence'].median().sort_values().index.tolist()
palette_list = [FUEL_COLORS.get(ft, '#95a5a6') for ft in sns_violin_order]
sns.violinplot(data=df_major, x='fuel_type', y='price_pence', order=sns_violin_order,
               palette=palette_list, ax=ax2, inner='quartile', cut=0)
ax2.set_ylabel('Price (pence per litre)')
ax2.set_xlabel('Fuel Type')
ax2.set_title('Price Density by Fuel Type (Major Fuels)')
fig2.tight_layout()
chart2_b64 = fig_to_base64(fig2)

# Chart 3: Price spread bar chart (range + IQR)
fig3, ax3 = plt.subplots(figsize=(10, 6))
spread_sorted = spread_stats.sort_values('price_range', ascending=True)
y_pos = range(len(spread_sorted))
ax3.barh(y_pos, spread_sorted['price_range'], color=PALETTE['secondary'], alpha=0.5, label='Full Range (Max − Min)')
ax3.barh(y_pos, spread_sorted['iqr'], color=PALETTE['accent'], alpha=0.8, label='IQR (Q3 − Q1)')
ax3.set_yticks(list(y_pos))
ax3.set_yticklabels(spread_sorted.index)
ax3.set_xlabel('Price Spread (pence per litre)')
ax3.set_title('Price Spread & IQR by Fuel Type')
ax3.legend(loc='lower right')
for i, (idx, row) in enumerate(spread_sorted.iterrows()):
    ax3.text(row['price_range'] + 1, i, f"{row['price_range']:.1f}p", va='center', fontsize=9)
fig3.tight_layout()
chart3_b64 = fig_to_base64(fig3)

# Chart 4: Update lag distribution
fig4, ax4 = plt.subplots(figsize=(10, 6))
# Cap at 200 hours for readability
lag_capped = df['update_lag_hours'].clip(upper=200)
lag_capped[lag_capped < 0] = 0  # handle any negative lags
for ft in major_fuels:
    subset = lag_capped[df['fuel_type'] == ft]
    ax4.hist(subset, bins=60, alpha=0.5, label=ft, color=FUEL_COLORS.get(ft, '#95a5a6'), density=True)
ax4.axvline(x=lag_overall_median, color='black', linestyle='--', linewidth=1.5, label=f'Overall Median ({lag_overall_median:.1f}h)')
ax4.axvline(x=stale_threshold, color=PALETTE['danger'], linestyle=':', linewidth=1.5, label=f'Stale Threshold ({stale_threshold}h)')
ax4.set_xlabel('Update Lag (hours)')
ax4.set_ylabel('Density')
ax4.set_title('Distribution of Update Lag by Fuel Type')
ax4.legend(fontsize=9)
fig4.tight_layout()
chart4_b64 = fig_to_base64(fig4)

# Chart 5: Fuels per station distribution
fig5, ax5 = plt.subplots(figsize=(8, 5))
fuels_per_station_counts = fuels_per_station.value_counts().sort_index()
ax5.bar(fuels_per_station_counts.index, fuels_per_station_counts.values, color=PALETTE['secondary'], edgecolor='white')
for i, (k, v) in enumerate(fuels_per_station_counts.items()):
    ax5.text(k, v + 50, str(v), ha='center', fontsize=10, fontweight='bold')
ax5.set_xlabel('Number of Fuel Types Reported')
ax5.set_ylabel('Number of Stations')
ax5.set_title('How Many Fuel Types Does Each Station Report?')
ax5.set_xticks(fuels_per_station_counts.index)
fig5.tight_layout()
chart5_b64 = fig_to_base64(fig5)

# Chart 6: Station coverage by fuel type
fig6, ax6 = plt.subplots(figsize=(10, 5))
spf_sorted = stations_per_fuel.sort_values(ascending=True)
colors_spf = [FUEL_COLORS.get(ft, '#95a5a6') for ft in spf_sorted.index]
ax6.barh(spf_sorted.index, spf_sorted.values, color=colors_spf, edgecolor='white')
for i, (ft, val) in enumerate(spf_sorted.items()):
    ax6.text(val + 30, i, f"{val:,}", va='center', fontsize=10)
ax6.set_xlabel('Number of Stations')
ax6.set_title('Station Coverage by Fuel Type')
fig6.tight_layout()
chart6_b64 = fig_to_base64(fig6)

# ── Build HTML ─────────────────────────────────────────────────────────────

# Format helpers
def fmt_ppl(val):
    return f"{val:.1f}p" if not pd.isna(val) else "—"

def fmt_num(val):
    return f"{val:,.0f}" if not pd.isna(val) else "—"

def fmt_hours(val):
    return f"{val:.1f}h" if not pd.isna(val) else "—"

def fmt_pct(val):
    return f"{val:.1f}%"

def fmt_date(dt):
    return dt.strftime('%Y-%m-%d %H:%M UTC')

# KPI cards
kpi_cards = f"""
<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin:20px 0;">
  <div class="kpi-card" style="background:linear-gradient(135deg,{PALETTE['primary']},{PALETTE['secondary']});">
    <div class="kpi-label">Total Records</div>
    <div class="kpi-value">{fmt_num(total_records)}</div>
  </div>
  <div class="kpi-card" style="background:linear-gradient(135deg,#8e44ad,#9b59b6);">
    <div class="kpi-label">Unique Stations</div>
    <div class="kpi-value">{fmt_num(unique_stations)}</div>
  </div>
  <div class="kpi-card" style="background:linear-gradient(135deg,{PALETTE['accent']},#d35400);">
    <div class="kpi-label">Fuel Types</div>
    <div class="kpi-value">{len(fuel_types)}</div>
  </div>
  <div class="kpi-card" style="background:linear-gradient(135deg,{PALETTE['success']},#1e8449);">
    <div class="kpi-label">Median Update Lag</div>
    <div class="kpi-value">{fmt_hours(lag_overall_median)}</div>
  </div>
</div>
"""

# Price stats table
price_table_rows = ""
for ft, row in price_stats.iterrows():
    price_table_rows += f"""
    <tr>
      <td><strong>{ft}</strong></td>
      <td>{fmt_num(row['Records'])}</td>
      <td>{fmt_ppl(row['Mean (ppl)'])}</td>
      <td>{fmt_ppl(row['Median (ppl)'])}</td>
      <td>{fmt_ppl(row['Std Dev'])}</td>
      <td>{fmt_ppl(row['Min (ppl)'])}</td>
      <td>{fmt_ppl(row['Max (ppl)'])}</td>
    </tr>"""

# Spread table
spread_table_rows = ""
for ft, row in spread_stats.iterrows():
    spread_table_rows += f"""
    <tr>
      <td><strong>{ft}</strong></td>
      <td>{fmt_ppl(row['min_val'])}</td>
      <td>{fmt_ppl(row['q25'])}</td>
      <td>{fmt_ppl(row['q75'])}</td>
      <td>{fmt_ppl(row['max_val'])}</td>
      <td>{fmt_ppl(row['iqr'])}</td>
      <td>{fmt_ppl(row['price_range'])}</td>
    </tr>"""

# Lag table
lag_table_rows = ""
for ft, row in lag_by_fuel.iterrows():
    lag_table_rows += f"""
    <tr>
      <td><strong>{ft}</strong></td>
      <td>{fmt_num(row['Records'])}</td>
      <td>{fmt_hours(row['Median Lag (hrs)'])}</td>
      <td>{fmt_hours(row['Mean Lag (hrs)'])}</td>
    </tr>"""

# Coverage table
coverage_table_rows = ""
for ft, count in stations_per_fuel.items():
    pct = count / unique_stations * 100
    coverage_table_rows += f"""
    <tr>
      <td><strong>{ft}</strong></td>
      <td>{fmt_num(count)}</td>
      <td>{fmt_pct(pct)}</td>
    </tr>"""

# Fuels per station table
fps_table_rows = ""
for n_fuels, n_stations in fuels_per_station_counts.items():
    pct = n_stations / unique_stations * 100
    fps_table_rows += f"""
    <tr>
      <td>{n_fuels}</td>
      <td>{fmt_num(n_stations)}</td>
      <td>{fmt_pct(pct)}</td>
    </tr>"""

# Most expensive / cheapest fuel finding
most_expensive = price_stats.index[0]
cheapest = price_stats.index[-1]
highest_spread = spread_stats.index[0]

# Build key findings
findings = []
findings.append(f"""<strong>Standard diesel (B7_STANDARD) and E10 unleaded dominate the dataset</strong>, accounting for the vast majority of price records. These two fuel types have the broadest station coverage and the most data points, making them the most reliable indicators of market conditions.""")

findings.append(f"""<strong>Consumers face significant price disparities.</strong> The {highest_spread} fuel type shows a price spread of {fmt_ppl(spread_stats.loc[highest_spread, 'price_range'])} per litre across stations. Even for the most common fuels, the IQR of {fmt_ppl(spread_stats.loc['B7_STANDARD', 'iqr'])} (B7_STANDARD) and {fmt_ppl(spread_stats.loc['E10', 'iqr'])} (E10) means consumers can save several pence per litre by shopping around — equating to roughly &pound;3&ndash;4 on a typical 55-litre fill.""")

findings.append(f"""<strong>Data freshness is generally good but with concerning outliers.</strong> The median update lag is {fmt_hours(lag_overall_median)}, indicating most prices are captured within minutes of being reported. However, {fmt_pct(stale_pct)} of records ({fmt_num(stale_count)}) have lags exceeding 48 hours, and {fmt_pct(very_stale_pct)} ({fmt_num(very_stale_count)}) exceed one week — suggesting some retailers are not updating their feeds promptly. This undermines the utility of the transparency scheme for consumers relying on current prices.""")

findings.append(f"""<strong>Premium fuels show wider price variation</strong> than standard grades. B7_PREMIUM has a spread of {fmt_ppl(spread_stats.loc['B7_PREMIUM', 'price_range'])} and IQR of {fmt_ppl(spread_stats.loc['B7_PREMIUM', 'iqr'])}, compared to B7_STANDARD's IQR of {fmt_ppl(spread_stats.loc['B7_STANDARD', 'iqr'])}. This suggests less price competition in the premium segment, where consumers may be less price-sensitive.""")

findings.append(f"""<strong>Station fuel type coverage varies significantly.</strong> While many stations report prices for 2&ndash;3 fuel types, coverage for specialty fuels like B7_PREMIUM and B10 is limited to a small fraction of stations. Policy makers should consider whether mandated reporting should be extended or more strictly enforced to ensure comprehensive consumer access to price information.""")

findings_list = "\n".join(f'<li style="margin-bottom:14px;">{f}</li>' for f in findings)

# Negative lag check
negative_lag_count = (df['update_lag_hours'] < 0).sum()

# ── Assemble HTML ──────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width,initial-scale=1.0">
<title>UK Retail Fuel Price Trend Analysis — February 2026</title>
<style>
  :root {{
    --primary: {PALETTE['primary']};
    --secondary: {PALETTE['secondary']};
    --accent: {PALETTE['accent']};
    --danger: {PALETTE['danger']};
    --success: {PALETTE['success']};
    --bg: #f5f6fa;
    --card-bg: #ffffff;
    --text: {PALETTE['dark_text']};
    --muted: #7f8c8d;
    --border: #e0e0e0;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    line-height: 1.65;
    color: var(--text);
    background: var(--bg);
    padding: 24px;
  }}
  .report-container {{
    max-width: 1100px;
