# Chart 4: Update lag distribution
fig4, ax4 = plt.subplots(figsize=(10, 6))
# Cap at 200 hours for readability
lag_capped = df['update_lag_hours'].clip(upper=200)
lag_capped[lag_capped < 0] = 0  # handle any negative lags
for ft in major_fuels:
    subset = lag_capped[df['fuel_type'] == ft]
    ax4.hist(subset, bins=60, alpha=0.5, label=ft, color=FUEL_COLORS.get(ft, '#95a5a6'), density=True)
ax4.axvline(x=lag_overall_median, color='black', linestyle='--', linewidth=1.5, label=f'Overall Median ({lag_overall_median:.1f}h)')
ax4.axvline(x=stale_threshold, color=PALETTE['danger'], linestyle=':', linewidth=1.5, label=f'Stale Threshold ({stale_threshold}h)')
ax4.set_xlabel('Update Lag (hours)')
