    font-size: 0.95rem;
    opacity: 0.85;
  }}
  .report-body {{ padding: 36px 48px 48px; }}
  h2 {{
    color: var(--primary);
    font-size: 1.35rem;
    font-weight: 700;
    margin: 36px 0 16px;
    padding-bottom: 8px;
    border-bottom: 2px solid var(--secondary);
  }}
  h2:first-child {{ margin-top: 0; }}
  h3 {{
    color: var(--text);
    font-size: 1.1rem;
    font-weight: 600;
    margin: 24px 0 10px;
  }}
  p, li {{ font-size: 0.95rem; }}
  p {{ margin-bottom: 12px; }}
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0 24px;
    font-size: 0.9rem;
  }}
  th {{
    background: var(--primary);
    color: white;
    padding: 10px 14px;
    text-align: left;
    font-weight: 600;
  }}
  td {{
    padding: 9px 14px;
